"""Install the defusedxml dependency required by the docx skill helper scripts."""
import subprocess
import sys

for cmd in (
    [sys.executable, "-m", "pip", "install", "defusedxml"],
    ["pip", "install", "defusedxml"],
    ["pip3", "install", "defusedxml"],
):
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
    except (FileNotFoundError, subprocess.TimeoutExpired) as exc:
        print(f"attempt {cmd[0]}: failed ({exc})")
        continue
    print(f"attempt {cmd[0]}: rc={result.returncode}")
    if result.returncode == 0:
        break
else:
    sys.exit("all pip install attempts failed")

import defusedxml  # noqa: E402

print("defusedxml import OK:", defusedxml.__version__ if hasattr(defusedxml, "__version__") else "installed")

